/* ─────────────────────────────────────────────────────────
 * BRAND COLOURS — one canonical colour per mark, for
 * <BrandIcon color="brand" />. Marks whose identity is black
 * (GitHub, Apple, X, Notion, Vercel, OpenAI…) resolve to --ink,
 * so they stay visible in dark mode; every other value is the
 * brand's published primary. These are logos, not UI colour:
 * they are exempt from the contrast rule and must never be
 * used for anything but the mark itself.
 * ───────────────────────────────────────────────────────── */
:root {
  --brand-github: var(--ink);
  --brand-google: #4285f4;
  --brand-apple: var(--ink);
  --brand-windows: #0078d4;
  --brand-slack: #4a154b;
  --brand-notion: var(--ink);
  --brand-figma: #f24e1e;
  --brand-linkedin: #0a66c2;
  --brand-x: var(--ink);
  --brand-twitter: #1d9bf0;
  --brand-instagram: #e4405f;
  --brand-facebook: #0866ff;
  --brand-messenger: #0084ff;
  --brand-youtube: #ff0000;
  --brand-tiktok: var(--ink);
  --brand-telegram: #26a5e4;
  --brand-whatsapp: #25d366;
  --brand-wechat: #07c160;
  --brand-skype: #00aff0;
  --brand-discord: #5865f2;
  --brand-stripe: #635bff;
  --brand-paypal: #003087;
  --brand-spotify: #1db954;
  --brand-soundcloud: #ff5500;
  --brand-android: #34a853;
  --brand-linux: var(--ink);
  --brand-chrome: #4285f4;
  --brand-openai: var(--ink);
  --brand-google-drive: #4285f4;
  --brand-google-play: #414141;
  --brand-app-store: #0d84ff;
  --brand-amazon: #ff9900;
  --brand-meta: #0467df;
  --brand-pinterest: #bd081c;
  --brand-reddit: #ff4500;
  --brand-threads: var(--ink);
  --brand-snapchat: #fffc00;
  --brand-twitch: #9146ff;
  --brand-mastodon: #6364ff;
  --brand-medium: var(--ink);
  --brand-tumblr: #36465d;
  --brand-behance: #1769ff;
  --brand-dribbble: #ea4c89;
  --brand-framer: #0055ff;
  --brand-sketch: #f7b500;
  --brand-gitlab: #fc6d26;
  --brand-codepen: var(--ink);
  --brand-codesandbox: var(--ink);
  --brand-replit: #f26207;
  --brand-stack-overflow: #f58025;
  --brand-dev-to: var(--ink);
  --brand-dropbox: #0061ff;
  --brand-teams: #6264a7;
  --brand-outlook: #0078d4;
  --brand-excel: #217346;
  --brand-word: #2b579a;
  --brand-powerpoint: #b7472a;
  --brand-steam: var(--ink);
  --brand-patreon: #ff424d;
  --brand-angular: #dd0031;
  --brand-markdown: var(--ink);
  --brand-coda: #f46a54;
  --brand-linktree: #43e55e;
}

/* BrandLogo dark variants: the component renders both where the brand
   publishes one; CSS picks, so components never branch on theme. */
.brand-logo-dark { display: none; }
[data-theme="dark"] .brand-logo-dark { display: inline; }
[data-theme="dark"] .brand-logo-light.brand-logo-has-dark { display: none; }

/* ─────────────────────────────────────────────────────────
 * FONTS — Urbanist, the default face (variable, weights 300–800)
 * Import this FIRST in your global stylesheet, before Tailwind:
 *   @import "./formic/styles/fonts.css";
 *   @import "tailwindcss";
 *   @import "./formic/styles/tokens.css";
 *   …
 * A CSS @import is only valid before other rules; anywhere later it is
 * dropped silently by Lightning CSS / PostCSS and the font never loads.
 * Self-hosting? Replace this file with your own @font-face rules and keep
 * the family name "Urbanist" so --font-sans in tokens.css still resolves.
 * ───────────────────────────────────────────────────────── */
@import url("https://fonts.googleapis.com/css2?family=Urbanist:wght@300..800&display=swap");

/* ─────────────────────────────────────────────────────────
 * FORMIC — the whole stylesheet stack in one import
 *
 *   @import "./formic/styles/fonts.css";   (first — a later @import is dropped)
 *   @import "tailwindcss";
 *   @import "./formic/styles/formic.css";
 *
 * Pulls in the tokens, the 5 palettes, the Tailwind v4 bridge, and the
 * per-component sheets (sidebar, records). Import the individual files
 * instead if you want to leave something out.
 * ───────────────────────────────────────────────────────── */
@import "./tokens.css";
@import "./themes.css";
@import "./tailwind-theme.css";
@import "./brands.css";
@import "./sidebar.css";
@import "./records.css";

/* ─────────────────────────────────────────────────────────
 * RECORDS TABLE — component stylesheet
 * Import after tokens.css when using components/RecordsTable.
 * Everything reads tokens; light/dark/palettes come free.
 * ───────────────────────────────────────────────────────── */

.records-shell { position: relative; width: 100%; }
.records-shell.is-fill { height: 100%; }

.records-scroll {
  max-height: 480px;
  overflow: auto;
  border: 1px solid var(--line);
  border-radius: var(--radius-card);
  background: var(--surface);
  box-shadow: var(--shadow-card);
}
.records-shell.is-fill .records-scroll { max-height: none; height: 100%; }

.records-table {
  border-collapse: separate;
  border-spacing: 0;
  table-layout: fixed;
  font-size: var(--text-caption);
}

/* ── headers ───────────────────────────────────────────── */
.records-header-cell {
  position: sticky;
  top: 0;
  z-index: 5;
  height: 36px;
  padding: 0;
  background: var(--surface);
  border-bottom: 1px solid var(--line);
  border-right: 1px solid var(--line);
  text-align: left;
  font-weight: 500;
  font-size: var(--text-small);
  color: var(--ink-3);
  white-space: nowrap;
  user-select: none;
}
.records-header-cell:last-child { border-right: none; }
.records-header-cell.is-colsel { background: var(--inset); }

.records-header-button {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  height: 35px;
  min-width: 0;
  padding: 0 10px;
  font: inherit;
  color: inherit;
  text-align: left;
  cursor: pointer;
  transition: background-color 150ms, color 150ms;
}
.records-header-button:hover { background: var(--hover); color: var(--ink); }
.records-header-icon { display: flex; color: var(--ink-3); flex-shrink: 0; }

.records-sort {
  position: absolute;
  right: 26px;
  top: 50%;
  translate: 0 -50%;
  display: flex;
  padding: 3px;
  border-radius: 4px;
  color: var(--ink-3);
  cursor: pointer;
  opacity: 0;
  transition: opacity 150ms, transform 220ms var(--ease-out-quint), background-color 150ms;
}
.records-header-cell:hover .records-sort,
.records-sort:focus-visible { opacity: 0.6; }
.records-sort:hover { background: var(--hover); }
.records-sort.is-visible { opacity: 1 !important; color: var(--ink-2); }

.records-resize-handle {
  position: absolute;
  top: 0;
  right: -4px;
  width: 8px;
  height: 100%;
  cursor: col-resize;
  z-index: 6;
}
.records-resize-handle::after {
  content: "";
  position: absolute;
  left: 3px;
  top: 0;
  width: 2px;
  height: 100%;
  background: transparent;
  transition: background-color 150ms;
}
.records-resize-handle:hover::after,
.records-resize-handle.is-resizing::after { background: var(--accent); }

/* ── cells ─────────────────────────────────────────────── */
.records-cell {
  height: 38px;
  padding: 0 10px;
  background: var(--surface);
  border-bottom: 1px solid var(--line);
  border-right: 1px solid var(--line);
  color: var(--ink);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  transition: background-color 150ms;
}
.records-cell:last-child { border-right: none; }
.records-cell.is-colsel { background: var(--hover); }
.records-row:hover .records-cell { background: var(--hover); }
.records-row.is-selected .records-cell { background: var(--accent-tint); }

.records-sticky-cell { position: sticky; left: 0; z-index: 3; }
thead .records-sticky-cell { z-index: 7; }
tfoot .records-sticky-cell { z-index: 5; }

.records-company-header {
  display: flex;
  align-items: center;
  gap: 8px;
  height: 35px;
  padding: 0 10px;
}
.records-company-header-button {
  font: inherit;
  color: inherit;
  cursor: pointer;
  padding: 2px 4px;
  margin: -2px -4px;
  border-radius: 4px;
  transition: background-color 150ms, color 150ms;
}
.records-company-header-button:hover { background: var(--hover); color: var(--ink); }
.records-company-cell { display: flex; align-items: center; gap: 8px; }
.records-rownum {
  width: 18px;
  flex-shrink: 0;
  text-align: right;
  font-size: var(--text-micro);
  font-variant-numeric: tabular-nums;
  color: var(--ink-3);
}
.records-company-mark {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  border-radius: var(--radius-sm);
  background: var(--inset);
  box-shadow: 0 0 0 1px var(--line);
  font-size: var(--text-micro);
  font-weight: 600;
  color: var(--ink-2);
}
.records-company-name {
  min-width: 0;
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-weight: 500;
  color: var(--ink);
  text-decoration: none;
}
.records-company-name.has-link:hover { text-decoration: underline; }

/* ── checkbox (appears on hover / when selected) ───────── */
.records-checkbox {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  cursor: pointer;
  opacity: 0;
  transition: opacity 150ms;
}
.records-header-cell .records-checkbox,
.records-row:hover .records-checkbox,
.records-row.is-selected .records-checkbox,
.records-checkbox:focus-within { opacity: 1; }
.records-checkbox input {
  position: absolute;
  inset: 0;
  opacity: 0;
  cursor: pointer;
  margin: 0;
}
.records-checkbox-box {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 15px;
  height: 15px;
  border-radius: 4px;
  background: var(--surface);
  box-shadow: inset 0 0 0 1.5px var(--line-strong);
  color: var(--canvas);
  transition: background-color 150ms, box-shadow 150ms;
}
.records-checkbox-box.is-active { background: var(--accent); box-shadow: none; }
.records-checkbox input:focus-visible + .records-checkbox-box {
  box-shadow: inset 0 0 0 1.5px var(--accent);
}
.records-checkbox-dash { width: 8px; height: 2px; border-radius: 1px; background: var(--canvas); }

/* ── tags — derived from one base hue per tag ──────────── */
.records-tags {
  position: relative;
  display: flex;
  align-items: center;
  gap: 4px;
  height: 100%;
  overflow: hidden;
}
.records-tags-measure {
  position: absolute;
  display: flex;
  gap: 4px;
  visibility: hidden;
  pointer-events: none;
}
.records-tag {
  display: inline-flex;
  align-items: center;
  height: 20px;
  padding: 0 7px;
  border-radius: var(--radius-sm);
  font-size: var(--text-tiny);
  font-weight: 500;
  white-space: nowrap;
  background: color-mix(in srgb, var(--tag-base) 16%, var(--surface));
  color: color-mix(in srgb, var(--tag-base) 50%, var(--ink)); /* 50% keeps ≥4.5:1 on every hue */
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--tag-base) 28%, transparent);
}
.records-more-tag {
  flex-shrink: 0;
  padding: 0 2px;
  font-size: var(--text-tiny);
  font-weight: 500;
  color: var(--ink-3);
}

/* ── cell content bits ─────────────────────────────────── */
.records-muted { color: var(--ink-3); }
.records-calc { display: inline-flex; align-items: center; gap: 8px; }
.records-pulse {
  width: 32px;
  height: 6px;
  border-radius: 999px;
  background-image: linear-gradient(90deg, var(--inset) 35%, var(--line-strong) 50%, var(--inset) 65%);
  background-size: 200% 100%;
  animation: shimmer-text 1.4s linear infinite;
}
.records-strength { display: inline-flex; align-items: center; gap: 7px; }
.records-strength-dot { width: 7px; height: 7px; flex-shrink: 0; border-radius: 999px; }
.records-link {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  max-width: 100%;
  color: var(--ink-2);
  text-decoration: none;
  transition: color 150ms;
}
.records-link:hover { color: var(--ink); text-decoration: underline; }
.records-link-label { min-width: 0; overflow: hidden; text-overflow: ellipsis; }

/* ── footer calculation row ────────────────────────────── */
.records-calculation-row .records-cell {
  position: sticky;
  bottom: 0;
  z-index: 4;
  height: 34px;
  border-bottom: none;
  border-top: 1px solid var(--line);
  font-size: var(--text-small);
  color: var(--ink-3);
}
.records-footer-value {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-variant-numeric: tabular-nums;
}
.records-calculation-number { color: var(--ink); font-weight: 600; }
.records-average { color: var(--ink-2); }
.records-add-calculation {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font: inherit;
  color: var(--ink-3);
  cursor: pointer;
  opacity: 0;
  transition: opacity 150ms, color 150ms;
}
.records-calculation-row:hover .records-add-calculation { opacity: 1; }
.records-add-calculation:hover { color: var(--ink); }
.records-add-calculation:focus-visible { opacity: 1; }

/* ─────────────────────────────────────────────────────────
 * SIDEBAR NAV — component stylesheet
 * Import after tokens.css when using components/SidebarNav.
 *
 * Collapse model: the inner column keeps its full width; the
 * <aside> narrows and clips it. Copy fades + slides out, so
 * only the left-aligned icons remain in the collapsed rail.
 * ───────────────────────────────────────────────────────── */

.sidebar-copy {
  transition:
    opacity var(--sidebar-copy-duration) var(--sidebar-easing),
    transform var(--sidebar-copy-duration) var(--sidebar-easing);
}
[data-sidebar-collapsed="true"] .sidebar-copy {
  opacity: 0;
  transform: translateX(calc(var(--sidebar-copy-offset) * -1));
  pointer-events: none;
}

.sidebar-workspace-control,
.sidebar-collapse-control {
  transition:
    opacity var(--sidebar-copy-duration) var(--sidebar-easing),
    background-color 150ms, color 150ms, transform 150ms;
}
[data-sidebar-collapsed="true"] .sidebar-workspace-control,
[data-sidebar-collapsed="true"] .sidebar-collapse-control {
  opacity: 0;
  pointer-events: none;
}

.sidebar-expand-control {
  opacity: 0;
  pointer-events: none;
  transition:
    opacity var(--sidebar-copy-duration) var(--sidebar-easing),
    background-color 150ms, color 150ms;
}
[data-sidebar-collapsed="true"] .sidebar-expand-control {
  opacity: 1;
  pointer-events: auto;
}

/* rows shrink to icon squares when collapsed — the highlight follows,
   so the active state reads as a compact square around the icon */
.sidebar-row { width: 208px; }
[data-sidebar-collapsed="true"] .sidebar-row { width: 36px; }
.sidebar-glide-highlight { left: 8px; width: 208px; }
[data-sidebar-collapsed="true"] .sidebar-glide-highlight { width: 36px; }

/* ─────────────────────────────────────────────────────────
 * TAILWIND v4 THEME BRIDGE
 *
 * Generates the utility classes the components use
 * (text-ink, bg-hover, rounded-control, shadow-card,
 * text-body, ease-out-quint, …) from the runtime tokens.
 *
 * In a Tailwind v4 project, import in this order:
 *   @import "./fonts.css";        (first — a later @import is dropped)
 *   @import "tailwindcss";
 *   @import "./tokens.css";
 *   @import "./themes.css";      (optional, for the 5 palettes)
 *   @import "./tailwind-theme.css";
 *
 * `inline` makes utilities reference var(--token) directly,
 * so light/dark and all palettes keep working at runtime.
 * ───────────────────────────────────────────────────────── */
@theme inline {
  /* Colors */
  --color-ink: var(--ink);
  --color-ink-2: var(--ink-2);
  --color-ink-3: var(--ink-3);
  --color-line: var(--line);
  --color-line-strong: var(--line-strong);
  --color-hover: var(--hover);
  --color-hover-2: var(--hover-2);
  --color-inset: var(--inset);
  --color-accent: var(--accent);
  --color-orange: var(--orange);
  --color-green: var(--green);
  --color-red: var(--red);
  --color-canvas: var(--canvas);
  --color-surface: var(--surface);
  --color-field: var(--field);
  --color-sidebar: var(--sidebar);
  --color-green-tint: var(--green-tint);
  --color-red-tint: var(--red-tint);
  --color-accent-tint: var(--accent-tint);
  --color-orange-tint: var(--orange-tint);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --color-chart-track: var(--chart-track);

  /* Typography */
  --font-sans: var(--font-sans);
  --font-mono: var(--font-mono);
  --text-lead: var(--text-lead);
  --text-body: var(--text-body);
  --text-caption: var(--text-caption);
  --text-small: var(--text-small);
  --text-tiny: var(--text-tiny);
  --text-micro: var(--text-micro);
  --text-nano: var(--text-nano);
  --text-title: var(--text-title);
  --text-heading: var(--text-heading);
  --text-display: var(--text-display);
  --text-display-lg: var(--text-display-lg);
  --text-display-xl: var(--text-display-xl);

  /* Radii */
  --radius-sm: var(--radius-sm);
  --radius-chip: var(--radius-chip);
  --radius-control: var(--radius-control);
  --radius-md: var(--radius-md);
  --radius-card: var(--radius-card);
  --radius-capsule: var(--radius-capsule);
  --radius-avatar: var(--radius-avatar);

  /* Shadows */
  --shadow-btn: var(--shadow-btn);
  --shadow-card: var(--shadow-card);
  --shadow-overlay: var(--shadow-overlay);
  --shadow-field: var(--shadow-field);

  /* Motion */
  --ease-out-quint: var(--ease-out-quint);
}

/* ─────────────────────────────────────────────────────────
 * THEMES — 10 palettes, each with light + dark variants (+ a custom one an app can generate)
 *
 * Load AFTER tokens.css. Activate with:
 *   <html data-palette="sage">   (paper | sage | twilight | clay | ocean | slate | sand | rose | plum | forest | custom)
 * "paper" is the default (tokens.css base values) — no
 * attribute needed. Dark mode combines freely with any
 * palette via data-theme="dark" or the OS preference.
 *
 * Palettes only override hue-carrying tokens; shadows,
 * status colors, and keyframes fall through to tokens.css.
 * ───────────────────────────────────────────────────────── */

/* ═══ SAGE — muted green ═══ */
:root[data-palette="sage"] {
  --ink: #1c211c; --ink-2: #5a635a; --ink-3: #687168;
  --line: #e2e7e0; --line-strong: #c9d1c7;
  --hover: #eef2ec; --hover-2: #e7ece5; --inset: #e7ece5;
  --canvas: #f6f8f4; --surface: #fcfdfb; --field: #f0f3ee;
  --accent: #40724f; --green-tint: #ecf6ee;
}

/* ═══ TWILIGHT — indigo ═══ */
:root[data-palette="twilight"] {
  --ink: #1b1d28; --ink-2: #5a5d70; --ink-3: #696c7f;
  --line: #e3e5ee; --line-strong: #c9ccde;
  --hover: #edeff6; --hover-2: #e6e8f2; --inset: #e6e8f2;
  --canvas: #f5f6fa; --surface: #fcfcfe; --field: #eff1f7;
  --accent: #4353d9;
}

/* ═══ CLAY — terracotta ═══ */
:root[data-palette="clay"] {
  --ink: #241d18; --ink-2: #675c53; --ink-3: #75695f;
  --line: #ece4dc; --line-strong: #d6cabf;
  --hover: #f3ece5; --hover-2: #ede5dd; --inset: #ede5dd;
  --canvas: #faf6f2; --surface: #fefcfa; --field: #f4eee8;
  --accent: #a44a22;
}

/* ═══ OCEAN — teal ═══ */
:root[data-palette="ocean"] {
  --ink: #172223; --ink-2: #556468; --ink-3: #617075;
  --line: #e0e8ea; --line-strong: #c5d2d6;
  --hover: #eaf1f2; --hover-2: #e3ebed; --inset: #e3ebed;
  --canvas: #f3f7f8; --surface: #fbfdfd; --field: #edf3f4;
  --accent: #0e7490;
}

/* ═══ SLATE — cool blue-grey (generated by scripts/palette.py from #4c6ef5) ═══ */
:root[data-palette="slate"] {
  --ink: #181a20; --ink-2: #585c65; --ink-3: #6b6f79;
  --line: #e2e5ec; --line-strong: #cbcfd9;
  --hover: #f0f2f8; --hover-2: #e9ecf3; --inset: #e6e9f0;
  --canvas: #f5f7fb; --surface: #fcfdff; --field: #f3f5fb;
  --accent: #345af4;
}

/* ═══ SAND — warm gold (generated by scripts/palette.py from #b7791f) ═══ */
:root[data-palette="sand"] {
  --ink: #1e1914; --ink-2: #625b53; --ink-3: #756e65;
  --line: #eae4de; --line-strong: #d5cec6;
  --hover: #f6f1ec; --hover-2: #f1ebe5; --inset: #eee8e2;
  --canvas: #faf6f3; --surface: #fefdfb; --field: #f9f4ef;
  --accent: #946219;
}

/* ═══ ROSE — pink (generated by scripts/palette.py from #d6336c) ═══ */
:root[data-palette="rose"] {
  --ink: #1f1819; --ink-2: #65595b; --ink-3: #786b6e;
  --line: #ece3e4; --line-strong: #d8ccce;
  --hover: #f7f0f1; --hover-2: #f3eaeb; --inset: #f0e7e8;
