  const lightAnchor = hexToRgb(LIGHT_ANCHOR)!;
  const darkAnchor = hexToRgb(DARK_ANCHOR)!;
  return {
    light: toHex(fitContrast(rgb, lightAnchor, -1)) /* darker until it holds on white */,
