  dark: { ink: "#f0efec", "ink-2": "#b0aeaa", "ink-3": "#8d8b86", line: "#2a2a29", "line-strong": "#3f3e3c", hover: "#232322", "hover-2": "#292928", inset: "#232322", canvas: "#131312", surface: "#1c1c1b", field: "#232322" },
