  for (let step = 0; step <= 100; step += 1) {
    const c = hslToRgb({ h, s, l: Math.min(1, Math.max(0, l + direction * step * 0.01)) });
    const cand = { r: Math.round(c.r), g: Math.round(c.g), b: Math.round(c.b) };
